const RATE = 10;

function helper(v) {
    return v + 1;
}

function inlined(n) {
    debugger;
    let a = helper(n);
    let b = helper(a);
    return a + b;
}

function constants(n) {
    debugger;
    let scaled = n * RATE;
    return scaled;
}

function sequencing(n) {
    debugger;
    step(n);
    step(n);
    step(n);
}

function conditional(n) {
    debugger;
    if (n) step(n);
    return n;
}

function step(v) { window.sink = v; }

globalThis.inlined = inlined;
globalThis.constants = constants;
globalThis.sequencing = sequencing;
globalThis.conditional = conditional;
